/* ===== Maintenance Management: screens and actions ===== */
const MM_TABS = [['dash', 'Dashboard'], ['requests', 'Requests'], ['wo', 'Work Orders'], ['pm', 'Preventive Maintenance'], ['technicians', 'Technicians'], ['vendors', 'Vendors'], ['reports', 'Reports'], ['setup', 'Setup']];
const mmNoAccess = () => can('mm_home', 'View') ? '' : '<div class="note bad"><b>Maintenance Management</b> is not enabled for your role.</div>';
const mmEntOf = a => a ? (a.branch || 'HO') : 'HO';
const mmAssetsOf = ent => (AT().assets || []).filter(a => (ent === 'HO' ? !a.branch : a.branch === ent) && !['Disposed', 'Missing'].includes(a.status) && (!mmDom() || (mmDom() === 'IT') === IT_CATS.includes(a.cat)));
const mmRows = (k, f) => MMX()[k].filter(r => mmInEnt(r.ent || r.school || r.branch) && mmDomOk(k, r) && (!f || f(r)));
const mmOwnOnly = () => !mmp('approve') && !mmp('edit');
const mmMask = m => mmp('edit') || !m ? (m || '') : m.slice(0, 2) + 'XXXXXX' + m.slice(-2);
const mmPill = s => pill(s, MM_DONE.includes(s) || s === 'Converted' || s === 'Active' ? 'ok' : MM_DEAD.includes(s) || s === 'Reopened' || s === 'Overdue' || s === 'Inactive' ? 'bad' : s === 'New' || s === 'Upcoming' || s === 'Waiting for Parts' || s === 'On Hold' ? 'warn' : '');
const mmPriPill = p => pill(p, p === 'Critical' ? 'bad' : p === 'High' ? 'warn' : '');
const mmKv = rows => `<table class="kv"><tbody>${rows.map(([k, x]) => `<tr><th>${k}</th><td>${x == null || x === '' ? '—' : x}</td></tr>`).join('')}</tbody></table>`;
const mmBars = (entries, empty) => { if (!entries.length) return `<p class="small muted">${empty}</p>`; const mx = Math.max(...entries.map(e => e[1]), 1); return `<div class="hbars">${entries.map(([l, n]) => `<div class="hb"><span>${esc(l)}</span><div class="hb-t"><span class="s0" style="width:${Math.max(4, Math.round(n / mx * 100))}%"></span></div><span class="hb-v">${n}</span></div>`).join('')}</div>`; };
const mmEdit = (fn, msg) => { const c = Store.clone(MMX()); const r = fn(c); mmSave(c, msg); return r; };
const mmWoOf = id => MMX().wos.find(x => x.id === id);
const mmReqOf = id => MMX().reqs.find(x => x.id === id);
const mmDays = (iso, d) => Math.round((new Date(iso) - new Date(d)) / 864e5);
const mmDt = s => s ? s.slice(0, 10) + (s.length > 10 ? ' ' + s.slice(11, 16) : '') : '—';
const mmEntBar = extra => `<div class="srf-strip2">${mmEntSel()}${extra || ''}</div>`;
const mmOverdueWo = t => !MM_DONE.includes(t.status) && !MM_DEAD.includes(t.status) && t.sla < mmNowCmp();
const mmOpenWo = t => !MM_DONE.includes(t.status) && !MM_DEAD.includes(t.status);
const mmFltSel = (k, label, opts, all) => `<label class="fld"><span>${label}</span><select data-act="uiSel" data-k="${k}"><option value="">${all}</option>${opts.map(o => `<option ${App.ui[k] === o ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select></label>`;
/* ---------- page ---------- */
function mmPageHtml(mod, label, note) {
  if (!can(mod, 'View')) return `<div class="note bad"><b>${label}</b> is not enabled for your role.</div>`; const M = MMX(); if (!M) return '<div class="note">Loading…</div>';
  const tab = MM_TABS.some(t => t[0] === pcTab('mm', 'dash')) ? pcTab('mm', 'dash') : 'dash';
  const tabs = pcTabs('mm', MM_TABS, 'dash');
  const body = { dash: mmDashV, requests: mmReqV, wo: mmWoV, pm: mmPmV, technicians: mmTechV, vendors: mmVendV, reports: mmRepV, setup: mmSetV }[tab]();
  return `<div class="note">${note}</div>${mmEntBar()}${tabs}${body}`;
}
PAGES.mm_home = {
  title: 'Maintenance Management', mod: 'mm_home', render() { return mmPageHtml('mm_home', 'Maintenance Management', '<b>Non-IT assets</b> (furniture, electrical, AC, plumbing, buildings, vehicles, labs…) are kept under the Maintenance Manager. Requests, work orders, preventive maintenance, vendors and costs: a request is approved into a work order, assigned to a technician or vendor, repaired, and confirmed. Overdue work orders escalate to the Maintenance Manager automatically. IT assets and IT tickets are managed in <b>IT Management</b>.'); }
};
PAGES.it_home = {
  title: 'IT Management', mod: 'it_home', render() { return mmPageHtml('it_home', 'IT Management', '<b>IT assets</b> (computers, networking, mobiles, software licences, CCTV and security devices) are kept under the IT Manager. IT requests, tickets, preventive maintenance, IT technicians and vendors follow the same approve → assign → repair → confirm workflow. Non-IT assets are managed in <b>Maintenance Management</b>.'); }
};
/* ---------- dashboard ---------- */
function mmDashV() {
  const M = MMX(), sc = mmScope(), inS = e => e === 'HO' ? sc.has('') : sc.has(e), wo = M.wos.filter(t => inS(t.ent) && mmDomOk('wos', t));
  const open = wo.filter(mmOpenWo), overdue = wo.filter(mmOverdueWo), done = wo.filter(t => MM_DONE.includes(t.status));
  const rt = wo.filter(t => t.log[1]).map(t => (new Date(t.log[1].d) - new Date(t.opened.slice(0, 10))) / 36e5), avgR = rt.length ? Math.round(rt.reduce((a, b) => a + b, 0) / rt.length) : 0;
  const ct = done.map(t => (new Date(t.closed || t.opened) - new Date(t.opened)) / 36e5), avgC = ct.length ? Math.round(ct.reduce((a, b) => a + b, 0) / ct.length) : 0;
  const pmD = mmPmDue(M, inS).length, pmO = mmPmOver(M, inS).length, cost = wo.reduce((a, t) => a + t.cost, 0), mCost = wo.filter(t => t.opened.slice(0, 7) === mmToday().slice(0, 7)).reduce((a, t) => a + t.cost, 0), esc_ = wo.filter(t => t.escalated && mmOpenWo(t)).length;
  const cnt = k => { const m = {}; wo.forEach(t => m[t[k]] = (m[t[k]] || 0) + 1); return Object.entries(m).sort((a, b) => b[1] - a[1]); };
  const byTech = {}; wo.forEach(t => { const k = t.tech || t.vendor; if (k) byTech[k] = (byTech[k] || 0) + 1; });
  const col = (n, c) => `<span class="${n ? c : 'green'}">${n}</span>`;
  const kp = `<div class="kpis k5">${bkKpi('Open work orders', open.length, 'not yet completed')}${bkKpi('Overdue', col(overdue.length, 'red'), 'past the SLA time')}${bkKpi('Completed', done.length, 'completed, verified or closed')}${bkKpi('Avg. response time', avgR + 'h', 'request to first action')}${bkKpi('Avg. completion time', avgC + 'h', 'raised to completed')}${bkKpi('PM due (7 days)', col(pmD, 'amber'), 'preventive schedules')}${bkKpi('PM overdue / missed', col(pmO, 'red'), 'schedules past due')}${bkKpi('Total maintenance cost', INR(cost), 'all work orders')}${bkKpi('This month', INR(mCost), mmToday().slice(0, 7))}${bkKpi('Escalated', col(esc_, 'red'), 'open work orders escalated to the manager')}</div>`;
  const right = mmp('add') ? `<button class="btn sm" data-act="mmRunEsc">Run escalation check</button>` : '';
  return `${kp}<div class="grid2">${card('By category', mmBars(cnt('problemCat').slice(0, 8), 'No work orders.'))}${card('By priority', mmBars(cnt('priority'), 'No work orders.'))}</div>${card('Technician / vendor workload', mmBars(Object.entries(byTech).sort((a, b) => b[1] - a[1]).slice(0, 12), 'Nothing assigned yet.'), { right, sub: 'Dashboard figures cover every institution in your access scope; the lists below follow the institution picked above.' })}`;
}
/* ---------- requests ---------- */
