const mmFile = id => { const el = document.getElementById(id) || null; const f = el && el.files && el.files[0]; if (f) return f.name; const S = App.ui._formSnap; return S && S[id] ? String(S[id]).replace(/^.*[\\/]/, '') : ''; };
