  const cats = `<div class="grid2">${pcFld('Request categories (comma separated)', `<input data-act="mmCats" value="${esc(M.cats.join(', '))}" ${ed ? '' : 'disabled'}>`)}${pcFld('Monthly maintenance budget (₹)', `<input type="number" min="0" data-act="mmBudget" value="${+M.budget || 0}" ${ed ? '' : 'disabled'}>`)}</div><p class="small muted">Response targets (SLA): Critical 4 h · High 24 h · Medium 72 h · Low 7 days. Work orders past their SLA escalate to the Maintenance Manager.</p>`;
  const log = table('mmLog', [{ h: 'When', k: l => tsLabel(l.t), t: 'text', x: l => l.t }, { h: 'Who', k: l => `${esc(l.by)}<div class="small muted">${esc(l.role || '')}</div>`, t: 'html', x: l => l.by }, { h: 'Action', k: l => l.e, t: 'text' }, { h: 'Record', k: l => l.ref, t: 'text', cls: 'small' }, { h: 'Remark', k: l => l.remark, t: 'text', cls: 'small wrap' }], (M.log || []).slice().reverse(), { compact: true, limit: 40, empty: 'No activity recorded yet.' });
