  mmReqRejectOk(t) { const why = (v('qRj') || '').trim(); if (!why) return toast('Enter a reason.', 'bad'); const id = t.dataset.k; mmEdit(c => { const r = c.reqs.find(y => y.id === id); r.status = 'Rejected'; r.rejectReason = why; r.log.push({ d: mmToday(), e: 'Rejected: ' + why, by: mmWho() }); mmLog(c, 'Maintenance request rejected', r.no, why); mmNotify('rejected', r, c); }, 'Request rejected.'); mmReqDoc(id); },
